 const deletePaper=async p=>{const linked=project.evidence.filter(e=>e.paperId===p.id).length;if(!window.confirm('Delete "'+p.name+'"? '+linked+' linked evidence records will also be removed.'))return;await fetch('/api/papers/'+p.id,{method:'DELETE'});update(pr=>({...pr,papers:pr.papers.filter(x=>x.id!==p.id),evidence:pr.evidence.filter(e=>e.paperId!==p.id),networkLinks:(pr.networkLinks||[]).filter(l=>!pr.evidence.some(e=>e.paperId===p.id&&(e.id===l.source_id||e.id===l.target_id)))}));if(paperId===p.id)setPaperId(project.papers.find(x=>x.id!==p.id)?.id||null);toast('Paper deleted')};
 const editPaper=p=>setPaperEditor({...p});
 const savePaperMetadata=()=>{if(!paperEditor)return;const name=String(paperEditor.name||'').trim();if(!name){toast('Please enter a display name for this PDF.');return;}update(p=>({...p,papers:p.papers.map(x=>x.id===paperEditor.id?{...x,...paperEditor,name,metadata_status:'user_confirmed'}:x)}));setPaperEditor(null);toast('Paper name and metadata saved.')};
 const renameTheme=(oldName)=>{const name=window.prompt('Rename theme',oldName)?.trim();if(!name||name===oldName||project.topics.includes(name))return;update(p=>({...p,topics:p.topics.map(t=>t===oldName?name:t),evidence:p.evidence.map(e=>e.theme===oldName?{...e,theme:name}:e)}));setMatches([])};
 const deleteTheme=(name)=>{if(!window.confirm('Delete theme "'+name+'"? Its evidence will be moved to Uncategorised.'))return;update(p=>({...p,topics:p.topics.filter(t=>t!==name),evidence:p.evidence.map(e=>e.theme===name?{...e,theme:'Uncategorised'}:e)}));setMatches([])};
 const saveEvidence=()=>{if(!selected)return;const record={...selected,id:crypto.randomUUID(),analysis:editing||selected.analysis,relationship,verifiedAt:new Date().toISOString(),verified:!!selected.paperId};update(p=>({...p,evidence:[...p.evidence,record]}));clearHighlightFocus();toast('Verified evidence saved to Evidence Map.');};
 const visibleThemes=activeThemes===null?(project?.topics||[]):activeThemes;
